/**
 * @fluent-i18n-toolkit v3
 *
 * Runtime translation helpers for the Vue apps: $t(), $_n() and $_x().
 *
 * The server localizes a PHP map (generated by i18n.node.js) onto a window
 * global, and every helper resolves by EXACT key match against that map. A
 * key that is missing returns the English source text, so nothing breaks
 * visibly; in a Vite dev build the helper logs `Missing translation: <key>`
 * once per key so you notice.
 *
 *   $t('text', ...args)            ordinary strings; %s, %d, %1$s placeholders filled from args
 *   $_n('one', 'many', count)      plural forms; count is also the first placeholder argument
 *   $_x('text', 'context', ...args) one English word that needs different translations in
 *                                  different places; resolves "context\x04text", then the plain key
 *
 * Keep the string literal inside the call: the generator scans for literal
 * arguments. $t(variable) only works for keys kept alive in the reserved
 * words file.
 *
 * Wire-up: the installer fills MAP_GLOBAL with this plugin's localized map
 * expression. Attach the exports to the app in the global mixin or via
 * app.config.globalProperties, replacing the previous one-line $t().
 */

// gettext's context separator, the same byte i18n.node.js writes into _x() keys.
const CONTEXT_DELIMITER = '\u0004';
const LOG_PREFIX = '[easy-code-manager]';
const warnedMissingKeys = new Set();

/**
 * The server-rendered string map. Some pages localize no map (or not even
 * the parent global), so always fall back to an empty object.
 */
function translationMap() {
    try {
        return (window.fluentSnippetAdmin.i18n) || {};
    } catch (e) {
        return {};
    }
}

/**
 * Dev-only warning that a key is missing from the map. Stripped from
 * production builds by Vite's dead-code elimination of import.meta.env.DEV.
 */
function warnIfMissing(key) {
    if (!(typeof import.meta !== 'undefined' && import.meta.env && import.meta.env.DEV) || warnedMissingKeys.has(key)) {
        return;
    }

    if (!Object.prototype.hasOwnProperty.call(translationMap(), key)) {
        warnedMissingKeys.add(key);
        console.warn(LOG_PREFIX + ' Missing translation: ' + key);
    }
}

/**
 * Substitute %s, %d and %1$s placeholders from `args`. Missing args leave
 * the placeholder in place so a bad call is visible rather than silent.
 */
export function applyPlaceholders(string, args) {
    if (!args || args.length === 0) {
        return string;
    }

    const regex = /%(\d*)\$?[sd]/g;
    let argIndex = 0; // position for unnumbered placeholders

    return String(string).replace(regex, (match, number) => {
        if (number) {
            const index = parseInt(number, 10) - 1;
            return index < args.length ? args[index] : match;
        }

        return argIndex < args.length ? args[argIndex++] : match;
    });
}

export function $t(string) {
    warnIfMissing(string);

    const translated = translationMap()[string] || string;

    return applyPlaceholders(translated, Array.prototype.slice.call(arguments, 1));
}

/**
 * Plural helper. Every count except exactly 1 (including non-numbers) takes
 * the plural, which matches how English and most target locales render it.
 */
export function $_n(singular, plural, count) {
    const number = parseFloat(String(count).replace(/,/g, ''));

    return $t(number === 1 ? singular : plural, count);
}

/**
 * Contextual translation, the JS counterpart of PHP's _x(). Placeholder args
 * follow the context: $_x('%1$s of %2$s', 'Pagination', page, total). Falls
 * back to the plain-text key.
 */
export function $_x(string, context) {
    const map = translationMap();
    const contextualKey = context + CONTEXT_DELIMITER + string;

    warnIfMissing(contextualKey);

    const translated = map[contextualKey] || map[string] || string;

    return applyPlaceholders(translated, Array.prototype.slice.call(arguments, 2));
}

export default $t;
